export function gc(cp) {
  const s = String(cp || "").padStart(5, "0");
  if (GPS[s]) return GPS[s];
  for (let i = 4; i >= 2; i--) {
    const p = s.slice(0, i);
    const k = Object.keys(GPS).find(x => x.startsWith(p));
    if (k) return GPS[k];
  }
  return [46.6, 2.2];
}

// Précision de la position résolue pour un CP :
//   "exact"   — CP présent dans le référentiel
//   "approx"  — repli sur un CP voisin (même préfixe 4→2 = même zone/département)
//   "unknown" — aucun repli possible : gc() renvoie le centre de la France (distances FAUSSES).
// Un lot "unknown" doit être signalé à l'utilisateur et exclu des propositions de boucle
// (arbitrage 2026-06-10 : signal visible, pas de blocage de saisie).
export function gcPrecision(cp) {
  const s = String(cp || "").padStart(5, "0");
  if (GPS[s]) return "exact";
  for (let i = 4; i >= 2; i--) {
    const p = s.slice(0, i);
    if (Object.keys(GPS).some(x => x.startsWith(p))) return "approx";
  }
  return "unknown";
}

// Le code postal est-il connu du référentiel — exactement, ou par un voisin de même préfixe ?
// `false` = `gc()` le placerait au centre de la France, et toute distance qui le touche est fausse.
// Fonction ADDITIVE (T0, défaut D3) : `gc` et `gcPrecision` ne changent pas, le moteur de
// production s'en sert tels quels. Mémoïsée : `gcPrecision` balaie le référentiel à chaque appel.
const CACHE_CP_CONNU = new Map();
export function cpConnu(cp) {
  const k = String(cp ?? "");
  let v = CACHE_CP_CONNU.get(k);
  if (v === undefined) { v = k.trim() !== "" && gcPrecision(k) !== "unknown"; CACHE_CP_CONNU.set(k, v); }
  return v;
}

// ── M2 : Correspondance CP → villes (pour auto-complétion saisie) ──
