// Retourne la liste des villes connues pour un CP (array vide si inconnu)
export function citiesFromCP(cp) {
  const s = String(cp || "").padStart(5, "0");
  return CP_CITIES[s] || [];
}

export function hav(a, b) {
  const R = 6371, r = x => x * Math.PI / 180;
  const dl = r(b[0] - a[0]), dn = r(b[1] - a[1]);
  const s = Math.sin(dl / 2) ** 2 + Math.cos(r(a[0])) * Math.cos(r(b[0])) * Math.sin(dn / 2) ** 2;
  const vol = R * 2 * Math.atan2(Math.sqrt(s), Math.sqrt(1 - s));
  const f = vol < 20 ? 1.4 : vol < 100 ? 1.35 : vol < 300 ? 1.3 : 1.25;
  return Math.round(vol * f);
}

